        final String notCached = service.getValue("1").toCompletableFuture().join();
        service.value = "2";

        // then
        final String fromCache = service.getValue("1").toCompletableFuture().join();
        assertEquals(notCached, fromCache);
        assertNotEquals("2", fromCache);
    }

