package ru.tinkoff.kora.annotation.processor.common;

import org.slf4j.Logger;
import org.slf4j.event.Level;

import javax.lang.model.element.Element;
import java.util.Collection;
import java.util.stream.Collectors;

public final class LogUtils {
    private LogUtils() {
    }

    public static void logElementsFull(Logger log, Level level, String prefix, Collection<? extends Element> elements) {
        if (elements == null || elements.isEmpty()) {
            return;
        }
        if (!log.isEnabledForLevel(level)) {
            return;
        }
        var message = elements.stream()
            .map(Object::toString)
            .sorted()
            .collect(Collectors.joining("\n"))
            .indent(4);
        log.makeLoggingEventBuilder(level).log("{}:\n{}", prefix, message);
    }

    public static void logElementsSimple(Logger log, Level level, String prefix, Collection<? extends Element> elements) {
        if (elements == null || elements.isEmpty()) {
            return;
        }
        if (!log.isEnabledForLevel(level)) {
            return;
        }
        var message = elements.stream()
            .map(e -> e.getSimpleName().toString())
            .sorted()
            .collect(Collectors.joining(", "))
            .indent(4);
        log.makeLoggingEventBuilder(level).log("{}:\n{}", prefix, message);
    }
}

