package com.squareup.javapoet;

import java.util.ArrayList;
import java.util.List;

public class TypeName {
    public static final TypeName VOID = new TypeName("void", true);
    public static final TypeName BOOLEAN = new TypeName("boolean", true);
    public static final TypeName BYTE = new TypeName("byte", true);
    public static final TypeName SHORT = new TypeName("short", true);
    public static final TypeName INT = new TypeName("int", true);
    public static final TypeName LONG = new TypeName("long", true);
    public static final TypeName CHAR = new TypeName("char", true);
    public static final TypeName FLOAT = new TypeName("float", true);
    public static final TypeName DOUBLE = new TypeName("double", true);

    protected final String name;
    protected final boolean primitive;

    protected TypeName(String name, boolean primitive) {
        this.name = name;
        this.primitive = primitive;
    }

    public TypeName(String name) {
        this(name, false);
    }

    public TypeName box() {
        if (!primitive) {
            return this;
        }
        return switch (name) {
            case "void" -> new TypeName("java.lang.Void");
            case "boolean" -> new TypeName("java.lang.Boolean");
            case "byte" -> new TypeName("java.lang.Byte");
            case "short" -> new TypeName("java.lang.Short");
            case "int" -> new TypeName("java.lang.Integer");
            case "long" -> new TypeName("java.lang.Long");
            case "char" -> new TypeName("java.lang.Character");
            case "float" -> new TypeName("java.lang.Float");
            case "double" -> new TypeName("java.lang.Double");
            default -> this;
        };
    }

    public static TypeName get(javax.lang.model.type.TypeMirror mirror) {
        String s = mirror.toString();
        return parse(s);
    }

    public static TypeName get(Object mirror) {
        if (mirror instanceof javax.lang.model.type.TypeMirror m) {
            return get(m);
        }
        return new TypeName(String.valueOf(mirror));
    }

    public static TypeName parse(String s) {
        if (s.equals("void")) return VOID;
        if (s.equals("boolean")) return BOOLEAN;
        if (s.equals("int")) return INT;
        if (s.equals("long")) return LONG;
        if (s.equals("java.lang.Void")) return new TypeName("java.lang.Void");
        int lt = s.indexOf('<');
        if (lt > 0) {
            String raw = s.substring(0, lt);
            String argsPart = s.substring(lt + 1, s.lastIndexOf('>'));
            List<TypeName> args = new ArrayList<>();
            for (String a : splitTopLevel(argsPart)) {
                args.add(parse(a.trim()));
            }
            return new ParameterizedTypeName(new ClassName(raw), args);
        }
        return new TypeName(s);
    }

    private static List<String> splitTopLevel(String s) {
        List<String> result = new ArrayList<>();
        int depth = 0;
        int start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '<') depth++;
            else if (c == '>') depth--;
            else if (c == ',' && depth == 0) {
                result.add(s.substring(start, i));
                start = i + 1;
            }
        }
        result.add(s.substring(start));
        return result;
    }

    public static ClassName get(Class<?> clazz) {
        return ClassName.get(clazz.getPackageName(), clazz.getSimpleName());
    }

    public String canonicalName() {
        return name;
    }

    public String simpleName() {
        int idx = name.lastIndexOf('.');
        int lt = name.indexOf('<');
        String base = lt > 0 ? name.substring(0, lt) : name;
        return idx < 0 ? base : base.substring(idx + 1);
    }

    public String toString() {
        return name;
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof TypeName t && t.name.equals(name) && t.primitive == primitive;
    }

    @Override
    public int hashCode() {
        return name.hashCode();
    }
}

