package com.squareup.javapoet;

import java.util.ArrayList;
import java.util.List;

public class CodeBlock {

    private final List<String> formatParts;
    private final List<Object> args;

    private CodeBlock(List<String> formatParts, List<Object> args) {
        this.formatParts = formatParts;
        this.args = args;
    }

    public boolean isEmpty() {
        return formatParts.isEmpty();
    }

    public static Builder builder() {
        return new Builder();
    }

    public String toString() {
        return render(0);
    }

    /**
     * Render this block as source code with indentation applied relative to an initial indent level.
     */
    public String render(int initialIndentLevel) {
        var writer = new Writer();
        writer.indentLevel = initialIndentLevel;
        writer.emit(this);
        return writer.out.toString();
    }

    static class Writer {
        StringBuilder out = new StringBuilder();
        String indent = "  ";
        int indentLevel = 0;
        boolean pendingIndent = true;
        int argIdx = 0;

        void emit(CodeBlock block) {
            for (String part : block.formatParts) {
                switch (part) {
                    case "$>" -> indentLevel++;
                    case "$<" -> indentLevel--;
                    case "$L" -> emitLiteral(block.args.get(argIdx++));
                    case "$N" -> emitText(String.valueOf(block.args.get(argIdx++)));
                    case "$S" -> emitText(stringLiteral(String.valueOf(block.args.get(argIdx++))));
                    case "$T" -> emitText(String.valueOf(block.args.get(argIdx++)));
                    default -> emitText(part);
                }
            }
        }

        void emitLiteral(Object o) {
            if (o instanceof CodeBlock cb) {
                emit(cb);
            } else {
                emitText(String.valueOf(o));
            }
        }

        void emitText(String s) {
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (c == '\n') {
                    out.append('\n');
                    pendingIndent = true;
                } else {
                    if (pendingIndent) {
                        out.append(indent.repeat(Math.max(0, indentLevel)));
                        pendingIndent = false;
                    }
                    out.append(c);
                }
            }
        }
    }

    static String stringLiteral(String value) {
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '\n' -> sb.append("\\n");
                case '\r' -> sb.append("\\r");
                case '\t' -> sb.append("\\t");
                case '"' -> sb.append("\\\"");
                case '\\' -> sb.append("\\\\");
                default -> sb.append(c);
            }
        }
        return sb.append('"').toString();
    }

    public static class Builder {
        private final List<String> formatParts = new ArrayList<>();
        private final List<Object> args = new ArrayList<>();

        public Builder add(String format, Object... args) {
            int p = 0;
            int argIdx = 0;
            while (p < format.length()) {
                int idx = format.indexOf('$', p);
                if (idx < 0) {
                    formatParts.add(format.substring(p));
                    break;
                }
                if (idx > p) {
                    formatParts.add(format.substring(p, idx));
                }
                char c = format.charAt(idx + 1);
                switch (c) {
                    case '$' -> {
                        formatParts.add("$");
                        p = idx + 2;
                    }
                    case 'L' -> {
                        formatParts.add("$L");
                        this.args.add(args[argIdx++]);
                        p = idx + 2;
                    }
                    case 'N' -> {
                        formatParts.add("$N");
                        this.args.add(args[argIdx++]);
                        p = idx + 2;
                    }
                    case 'S' -> {
                        formatParts.add("$S");
                        this.args.add(args[argIdx++]);
                        p = idx + 2;
                    }
                    case 'T' -> {
                        formatParts.add("$T");
                        this.args.add(args[argIdx++]);
                        p = idx + 2;
                    }
                    case '>' -> {
                        formatParts.add("$>");
                        p = idx + 2;
                    }
                    case '<' -> {
                        formatParts.add("$<");
                        p = idx + 2;
                    }
                    default -> throw new IllegalArgumentException("Unknown format char: " + c);
                }
            }
            return this;
        }

        public Builder add(CodeBlock codeBlock) {
            formatParts.addAll(codeBlock.formatParts);
            args.addAll(codeBlock.args);
            return this;
        }

        public Builder addStatement(String format, Object... args) {
            add(format, args);
            add(";\n");
            return this;
        }

        public Builder beginControlFlow(String controlFlow, Object... args) {
            add(controlFlow, args);
            add(" {\n");
            indent();
            return this;
        }

        public Builder endControlFlow() {
            unindent();
            add("}\n");
            return this;
        }

        public Builder endControlFlow(String controlFlow, Object... args) {
            unindent();
            add("}");
            add(controlFlow, args);
            add("\n");
            return this;
        }

        public Builder nextControlFlow(String controlFlow, Object... args) {
            unindent();
            add("} ");
            add(controlFlow, args);
            add(" {\n");
            indent();
            return this;
        }

        public Builder indent() {
            formatParts.add("$>");
            return this;
        }

        public Builder unindent() {
            formatParts.add("$<");
            return this;
        }

        public boolean isNotEmpty() {
            return !formatParts.isEmpty();
        }

        public CodeBlock build() {
            return new CodeBlock(List.copyOf(formatParts), List.copyOf(args));
        }
    }
}

