    public static void main(String[] args) throws IOException {
        var newAspect = new LogAspect(new FakeProcessingEnvironment());
        var oldAspect = new ru.tinkoff.kora.logging.aspect.old.LogAspect(new FakeProcessingEnvironment());

        var outDir = Path.of(args.length > 0 ? args[0] : "/tmp/opencode/harness/gen");

        StringBuilder report = new StringBuilder();
        int failures = 0;
        for (var s : SCENARIOS) {
            var method = build(s);
            var newOut = run(newAspect, method);
            var oldOut = run(oldAspect, method);

            var newBody = newOut.body();
            var oldBody = oldOut.body();

            report.append("==================== ").append(s.id()).append(" ====================\n");
            report.append("----- NEW -----\n").append(newBody).append("\n");
            report.append("----- OLD -----\n").append(oldBody).append("\n");

            if (normalize(newBody).equals(normalize(oldBody))) {
                report.append("STRUCTURE: IDENTICAL\n");
            } else {
                report.append("STRUCTURE: DIFFERS (new vs old)\n");
                report.append("NEW: ").append(normalize(newBody)).append("\n");
                report.append("OLD: ").append(normalize(oldBody)).append("\n");
                failures++;
            }
            report.append("\n");

            // generate & compile the proxy for the NEW output
            var pkg = "gen." + s.id();
            var targetFile = writeTarget(pkg, s);
            var proxyFile = writeProxy(pkg, s, newOut);
            boolean compiled = compile(new java.util.List[]{List.of(targetFile), List.of(proxyFile)}, pkg);
            report.append("COMPILE NEW proxy: ").append(compiled ? "OK" : "FAIL").append("\n\n");
            if (!compiled) failures++;
        }

        Files.writeString(outDir.resolve("report.txt"), report.toString());
        System.out.println("REPORT written, structural failures=" + failures);
        System.out.println("(report at " + outDir.resolve("report.txt") + ")");
    }

    static String renderSignature(Scenario s, boolean includeReturn) {
        StringBuilder sb = new StringBuilder();
        if (includeReturn) {
            sb.append(typeText(s.returnType())).append(' ');
        }
        sb.append("test(");
        for (int i = 0; i < s.params().size(); i++) {
            if (i > 0) sb.append(", ");
            sb.append(typeText(s.params().get(i).typeText())).append(' ').append(s.params().get(i).name());
        }
        sb.append(')');
        return sb.toString();
    }

    static String typeText(String t) {
        return t;
    }

    static String retTypeText(Scenario s, boolean boxed) {
        if (s.returnKind() == TypeKind.VOID) return "void";
        String t = s.returnType();
        int lt = t.indexOf('<');
        String core = lt > 0 ? t.substring(0, lt) : t;
        String args = lt > 0 ? t.substring(lt) : "";
        return core + args;
    }

    static Path writeTarget(String pkg, Scenario s) throws IOException {
        Path dir = Path.of("/tmp/opencode/harness/gen", pkg.replace('.', '/'));
        Files.createDirectories(dir);
        var sb = new StringBuilder();
        sb.append("package ").append(pkg).append(";\n\n");
        sb.append("public class Target {\n");
        sb.append("  public Target() {}\n");
        sb.append("  public ").append(renderSignature(s, true)).append(" {\n");
        if (s.returnKind() == TypeKind.VOID) {
            sb.append("    return;\n");
        } else if (s.returnType().startsWith("reactor.core.publisher.Mono")) {
            sb.append("    return reactor.core.publisher.Mono.just(null);\n");
        } else if (s.returnType().startsWith("java.util.concurrent.CompletionStage") || s.returnType().startsWith("java.util.concurrent.CompletableFuture")) {
            sb.append("    return java.util.concurrent.CompletableFuture.completedFuture(null);\n");
        } else {
            sb.append("    return ").append(literalFor(s.returnType())).append(";\n");
        }
        sb.append("  }\n");
        sb.append("}\n");
        Files.writeString(dir.resolve("Target.java"), sb.toString());
        return dir.resolve("Target.java");
    }

    static String literalFor(String t) {
        if (t.equals("java.lang.String")) return "\"hello\"";
        if (t.equals("int")) return "1";
        if (t.equals("boolean")) return "true";
        return "null";
    }

    static Path writeProxy(String pkg, Scenario s, Outcome out) throws IOException {
        Path dir = Path.of("/tmp/opencode/harness/gen", pkg.replace('.', '/'));
        Files.createDirectories(dir);
        var sb = new StringBuilder();
        sb.append("package ").append(pkg).append(";\n\n");
        sb.append("public final class $Target__AopProxy extends Target {\n");
        // fields
        sb.append("  private final org.slf4j.Logger ").append(out.loggerField()).append(";\n");
        for (var p : out.ff().params()) {
            if (p[0].equals("p1")) continue;
            sb.append("  private final @jakarta.annotation.Nullable ").append(p[1]).append(' ').append(p[0]).append(";\n");
        }
        // constructor
        sb.append("  public $Target__AopProxy(");
        boolean first = true;
        List<String> ctorParams = new ArrayList<>();
        // loggerFactory param
        sb.append("org.slf4j.ILoggerFactory p1");
        ctorParams.add("p1");
        for (var p : out.ff().params()) {
            if (p[0].equals("p1")) continue;
            sb.append(", @jakarta.annotation.Nullable ").append(p[1]).append(' ').append(p[0]);
            ctorParams.add(p[0]);
        }
        sb.append(") {\n");
        sb.append("    super();\n");
        var init = out.ff().initials().get(0);
        // initializer text like: p1.getLogger("com.example.Target.test")
        var initExpr = init[2].replace("p1", "p1");
        sb.append("    this.").append(init[0]).append(" = ").append(initExpr).append(";\n");
        for (var p : out.ff().params()) {
            if (p[0].equals("p1")) continue;
            sb.append("    this.").append(p[0]).append(" = ").append(p[0]).append(";\n");
        }
        sb.append("  }\n\n");
        // body method
        sb.append("  private ").append(renderSignature(s, true)).append(" {\n");
        for (String line : out.body().split("\n")) {
            sb.append("    ").append(line).append("\n");
        }
        sb.append("  }\n\n");
        // public delegating method
        sb.append("  public ").append(renderSignature(s, true)).append(" {\n");
        if (s.returnKind() != TypeKind.VOID) sb.append("    return ");
        sb.append("    this.test(");
        for (int i = 0; i < s.params().size(); i++) {
            if (i > 0) sb.append(", ");
            sb.append(s.params().get(i).name());
        }
        sb.append(");\n");
        sb.append("  }\n");
        sb.append("}\n");
        Files.writeString(dir.resolve("$Target__AopProxy.java"), sb.toString());
        return dir.resolve("$Target__AopProxy.java");
    }

    static boolean compile(List<Path> files, String pkg) {
        var cmd = new ArrayList<String>();
        cmd.add("javac");
        cmd.add("-proc:none");
        cmd.add("-d");
        cmd.add("/tmp/opencode/harness/gen-classes");
        cmd.add("-classpath");
        cmd.add(System.getProperty("java.class.path"));
        for (var f : files) cmd.add(f.toString());
        try {
            var pb = new ProcessBuilder(cmd);
            pb.redirectErrorStream(true);
            var p = pb.start();
            var out = new String(p.getInputStream().readAllBytes());
            int code = p.waitFor();
            if (code != 0) {
                System.out.println("javac " + pkg + " failed:\n" + out);
                return false;
            }
            return true;
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

