package driver;

import com.squareup.javapoet.CodeBlock;
import fake.FakeDeclaredType;
import fake.FakeElement;
import fake.FakeExecutableElement;
import fake.FakeProcessingEnvironment;
import fake.FakeTypeMirror;
import fake.FakeVariableElement;
import ru.tinkoff.kora.aop.annotation.processor.KoraAspect;
import ru.tinkoff.kora.logging.aspect.LogAspect;

import javax.lang.model.element.ExecutableElement;
import javax.lang.model.element.TypeKind;
import javax.lang.model.type.TypeMirror;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class Driver {

    static final String LOG_ANN = "ru.tinkoff.kora.logging.common.annotation.Log";
    static final String LOG_IN_ANN = "ru.tinkoff.kora.logging.common.annotation.Log.in";
    static final String LOG_OUT_ANN = "ru.tinkoff.kora.logging.common.annotation.Log.out";
    static final String LOG_OFF_ANN = "ru.tinkoff.kora.logging.common.annotation.Log.off";
    static final String LOG_RESULT_ANN = "ru.tinkoff.kora.logging.common.annotation.Log.result";
    static final String MAPPING_ANN = "ru.tinkoff.kora.common.Mapping";

    static final String BODY_METHOD = "_test_AopProxy_LogAspect";
    static final Path GEN_DIR = Path.of("/tmp/opencode/harness/gen");

    record Param(String name, String typeText, TypeKind kind, List<String[]> annotations) {
    }

    record Scenario(String id, List<String[]> methodAnnotations, String returnType, TypeKind returnKind,
                    List<Param> params, String mapperClass) {
    }

    static FakeTypeMirror type(String text, TypeKind kind) {
        if (kind == TypeKind.DECLARED) {
            List<FakeTypeMirror> args = new ArrayList<>();
            String core = text;
            int lt = text.indexOf('<');
            if (lt > 0) {
                core = text.substring(0, lt);
                String argsPart = text.substring(lt + 1, text.lastIndexOf('>'));
                for (String a : argsPart.split(",")) {
                    args.add(new FakeTypeMirror(a.trim(), TypeKind.DECLARED));
                }
            }
            return new FakeDeclaredType(core, args);
        }
        return new FakeTypeMirror(text, kind);
    }

    static FakeExecutableElement build(Scenario s) {
        var method = new FakeExecutableElement("test");
        var enclosing = new FakeElement("com.example.Target", javax.lang.model.element.ElementKind.CLASS);
        method.withEnclosing(enclosing);
        for (var a : s.methodAnnotations()) {
            method.addAnnotation(a[0], Map.of("value", a.length > 1 ? a[1] : "INFO"));
        }
        if (s.mapperClass() != null) {
            method.addAnnotation(MAPPING_ANN, Map.of("value", s.mapperClass()));
        }
        method.withReturnType(type(s.returnType(), s.returnKind()));
        for (var p : s.params()) {
            var v = new FakeVariableElement(p.name()).withType(type(p.typeText(), p.kind()));
            for (var a : p.annotations()) {
                v.addAnnotation(a[0], Map.of("value", a[1]));
            }
            method.withParameter(v);
        }
        return method;
    }

    static class FakeFieldFactory implements KoraAspect.FieldFactory {
        final List<String[]> params = new ArrayList<>();
        final List<String[]> initials = new ArrayList<>();

        @Override
        public String constructorParam(com.squareup.javapoet.TypeName type, List<com.squareup.javapoet.AnnotationSpec> annotations) {
            var name = "p" + (params.size() + 1);
            params.add(new String[]{name, type.toString()});
            return name;
        }

        @Override
        public String constructorInitialized(com.squareup.javapoet.TypeName type, CodeBlock initializer) {
            var name = "l" + (initials.size() + 1);
            initials.add(new String[]{name, type.toString(), initializer.render(0)});
            return name;
        }
    }

    record Outcome(String body, String loggerField, FakeFieldFactory ff) {
    }

    static Outcome run(LogAspect aspect, ExecutableElement method) {
        var ff = new FakeFieldFactory();
        var ctx = new KoraAspect.AspectContext(ff);
        var result = aspect.apply(method, "super.test", ctx);
        var body = ((KoraAspect.ApplyResult.MethodBody) result).codeBlock();
        return new Outcome(body.render(0), "l1", ff);
    }

    static final List<Scenario> SCENARIOS = new ArrayList<>();

    static {
        SCENARIOS.add(new Scenario("blockingVoidLog", List.of(new String[]{LOG_ANN}),
            "void", TypeKind.VOID, List.of(), null));
        SCENARIOS.add(new Scenario("blockingInOnly", List.of(new String[]{LOG_IN_ANN}),
            "void", TypeKind.VOID, List.of(), null));
        SCENARIOS.add(new Scenario("blockingOutOnly", List.of(new String[]{LOG_OUT_ANN}),
            "void", TypeKind.VOID, List.of(), null));
        SCENARIOS.add(new Scenario("blockingOutResult", List.of(new String[]{LOG_OUT_ANN}),
            "java.lang.String", TypeKind.DECLARED, List.of(), null));
        SCENARIOS.add(new Scenario("blockingOutResultSameLevel", List.of(
            new String[]{LOG_OUT_ANN}, new String[]{LOG_RESULT_ANN, "INFO"}),
            "java.lang.String", TypeKind.DECLARED, List.of(), null));
        SCENARIOS.add(new Scenario("blockingLogArgs", List.of(new String[]{LOG_IN_ANN}),
            "void", TypeKind.VOID, List.of(
                new Param("arg1", "java.lang.String", TypeKind.DECLARED, List.of()),
                new Param("arg2", "java.lang.String", TypeKind.DECLARED, List.of(new String[]{LOG_ANN, "TRACE"})),
                new Param("arg3", "java.lang.String", TypeKind.DECLARED, List.of(new String[]{LOG_OFF_ANN, ""})),
                new Param("arg4", "int", TypeKind.INT, List.of()),
                new Param("arg5", "boolean", TypeKind.BOOLEAN, List.of())
            ), null));
        SCENARIOS.add(new Scenario("blockingLogArgsMapper", List.of(new String[]{LOG_IN_ANN}),
            "void", TypeKind.VOID, List.of(
                new Param("arg1", "java.lang.String", TypeKind.DECLARED, List.of())
            ), "com.example.MyLogArgMapper"));
        SCENARIOS.add(new Scenario("blockingOutResultMapper", List.of(new String[]{LOG_OUT_ANN}),
            "java.lang.String", TypeKind.DECLARED, List.of(), "com.example.MyLogArgMapper"));
        SCENARIOS.add(new Scenario("monoLog", List.of(new String[]{LOG_ANN}),
            "reactor.core.publisher.Mono<java.lang.String>", TypeKind.DECLARED, List.of(), null));
        SCENARIOS.add(new Scenario("monoVoidLog", List.of(new String[]{LOG_ANN}),
            "reactor.core.publisher.Mono<java.lang.Void>", TypeKind.DECLARED, List.of(), null));
        SCENARIOS.add(new Scenario("monoOutResult", List.of(new String[]{LOG_OUT_ANN}),
            "reactor.core.publisher.Mono<java.lang.String>", TypeKind.DECLARED, List.of(), null));
        SCENARIOS.add(new Scenario("monoOutResultSameLevel", List.of(
            new String[]{LOG_OUT_ANN}, new String[]{LOG_RESULT_ANN, "INFO"}),
            "reactor.core.publisher.Mono<java.lang.String>", TypeKind.DECLARED, List.of(), null));
        SCENARIOS.add(new Scenario("futureLog", List.of(new String[]{LOG_ANN}),
            "java.util.concurrent.CompletionStage<java.lang.String>", TypeKind.DECLARED, List.of(), null));
        SCENARIOS.add(new Scenario("futureVoidLog", List.of(new String[]{LOG_OUT_ANN}),
            "java.util.concurrent.CompletionStage<java.lang.Void>", TypeKind.DECLARED, List.of(), null));
        SCENARIOS.add(new Scenario("futureOutResult", List.of(new String[]{LOG_OUT_ANN}),
            "java.util.concurrent.CompletionStage<java.lang.String>", TypeKind.DECLARED, List.of(), null));
    }

    static String normalize(String s) {
        return s.replaceAll("\\s+", " ").trim();
    }

    public static void main(String[] args) throws IOException {
        var newAspect = new LogAspect(new FakeProcessingEnvironment());
        var oldAspect = new ru.tinkoff.kora.logging.aspect.old.LogAspect(new FakeProcessingEnvironment());

        Files.createDirectories(GEN_DIR);

        StringBuilder report = new StringBuilder();
        int failures = 0;
        for (var s : SCENARIOS) {
            var method = build(s);
            var newOut = run(newAspect, method);
            var oldOut = run(oldAspect, method);

            var newBody = newOut.body();
            var oldBody = oldOut.body();

            report.append("==================== ").append(s.id()).append(" ====================\n");
            report.append("----- NEW -----\n").append(newBody).append("\n");
            report.append("----- OLD -----\n").append(oldBody).append("\n");

            if (normalize(newBody).equals(normalize(oldBody))) {
                report.append("STRUCTURE: IDENTICAL\n");
            } else {
                report.append("STRUCTURE: DIFFERS (new vs old)\n");
                report.append("NEW: ").append(normalize(newBody)).append("\n");
                report.append("OLD: ").append(normalize(oldBody)).append("\n");
                failures++;
            }
            report.append("\n");

            var targetFile = writeTarget(s);
            var proxyFile = writeProxy(s, newOut);
            boolean compiled = compile(List.of(targetFile, proxyFile), s.id());
            report.append("COMPILE NEW proxy: ").append(compiled ? "OK" : "FAIL").append("\n\n");
            if (!compiled) failures++;
        }

        Files.writeString(GEN_DIR.resolve("report.txt"), report.toString());
        System.out.println("REPORT written, failures=" + failures);
    }

    static String renderSignature(Scenario s, boolean includeReturn) {
        StringBuilder sb = new StringBuilder();
        if (includeReturn) {
            sb.append(s.returnType()).append(' ');
        }
        sb.append("test(");
        for (int i = 0; i < s.params().size(); i++) {
            if (i > 0) sb.append(", ");
            sb.append(s.params().get(i).typeText()).append(' ').append(s.params().get(i).name());
        }
        sb.append(')');
        return sb.toString();
    }

    static Path writeTarget(Scenario s) throws IOException {
        var pkg = "gen." + s.id();
        Path dir = GEN_DIR.resolve(pkg.replace('.', '/'));
        var sb = new StringBuilder();
        sb.append("package ").append(pkg).append(";\n\n");
        sb.append("public class Target {\n");
        sb.append("  public Target() {}\n");
        sb.append("  public ").append(renderSignature(s, true)).append(" {\n");
        if (s.returnKind() == TypeKind.VOID) {
            sb.append("    return;\n");
        } else if (s.returnType().equals("reactor.core.publisher.Mono<java.lang.String>")
            || s.returnType().equals("reactor.core.publisher.Mono<java.lang.Void>")) {
            sb.append("    return reactor.core.publisher.Mono.just(null);\n");
        } else if (s.returnType().startsWith("java.util.concurrent.")) {
            sb.append("    return java.util.concurrent.CompletableFuture.completedFuture(null);\n");
        } else {
            sb.append("    return ").append(literalFor(s.returnType())).append(";\n");
        }
        sb.append("  }\n");
        sb.append("}\n");
        Files.writeString(dir.resolve("Target.java"), sb.toString());
        return dir.resolve("Target.java");
    }

    static String literalFor(String t) {
        if (t.equals("java.lang.String")) return "\"hello\"";
        if (t.equals("int")) return "1";
        if (t.equals("boolean")) return "true";
        return "null";
    }

    static Path writeProxy(Scenario s, Outcome out) throws IOException {
        var pkg = "gen." + s.id();
        Path dir = GEN_DIR.resolve(pkg.replace('.', '/'));
        var sb = new StringBuilder();
        sb.append("package ").append(pkg).append(";\n\n");
        sb.append("public final class $Target__AopProxy extends Target {\n");
        sb.append("  private final org.slf4j.Logger ").append(out.loggerField()).append(";\n");
        for (var p : out.ff().params()) {
            if (p[0].equals("p1")) continue;
            sb.append("  private final @jakarta.annotation.Nullable ").append(p[1]).append(' ').append(p[0]).append(";\n");
        }
        sb.append("  public $Target__AopProxy(org.slf4j.ILoggerFactory p1");
        for (var p : out.ff().params()) {
            if (p[0].equals("p1")) continue;
            sb.append(", @jakarta.annotation.Nullable ").append(p[1]).append(' ').append(p[0]);
        }
        sb.append(") {\n");
        sb.append("    super();\n");
        var init = out.ff().initials().get(0);
        sb.append("    this.").append(init[0]).append(" = ").append(init[2]).append(";\n");
        for (var p : out.ff().params()) {
            if (p[0].equals("p1")) continue;
            sb.append("    this.").append(p[0]).append(" = ").append(p[0]).append(";\n");
        }
        sb.append("  }\n\n");
        sb.append("  private ").append(renderSignature(s, true)).append(" {\n");
        for (String line : out.body().split("\n", -1)) {
            sb.append("    ").append(line).append("\n");
        }
        sb.append("  }\n\n");
        sb.append("  public ").append(renderSignature(s, true)).append(" {\n");
        if (s.returnKind() != TypeKind.VOID) sb.append("    return ");
        sb.append("    this.").append(BODY_METHOD).append("(");
        for (int i = 0; i < s.params().size(); i++) {
            if (i > 0) sb.append(", ");
            sb.append(s.params().get(i).name());
        }
        sb.append(");\n");
        sb.append("  }\n");
        sb.append("}\n");
        Files.writeString(dir.resolve("$Target__AopProxy.java"), sb.toString());
        return dir.resolve("$Target__AopProxy.java");
    }

    static boolean compile(List<Path> files, String label) {
        var cmd = new ArrayList<String>();
        cmd.add("javac");
        cmd.add("-proc:none");
        cmd.add("-d");
        cmd.add(GEN_DIR.resolve("classes").toString());
        cmd.add("-classpath");
        cmd.add(System.getProperty("java.class.path"));
        for (var f : files) cmd.add(f.toString());
        try {
            var pb = new ProcessBuilder(cmd);
            pb.redirectErrorStream(true);
            var p = pb.start();
            var out = new String(p.getInputStream().readAllBytes());
            int code = p.waitFor();
            if (code != 0) {
                System.out.println("javac " + label + " failed:\n" + out);
                return false;
            }
            return true;
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

