            var s = sr.scenario();
            var loggerName = "com.example.Target.test";
            var newCalls = new java.util.ArrayList<RecCall>();
            var oldCalls = new java.util.ArrayList<RecCall>();

            report.append("--- scenario ").append(s.id()).append(" ---\n");
            for (var run : sr.runs()) {
                report.append("run levels=").append(java.util.Arrays.toString(run.levels())).append("\n");
