    record RecCall(String level, String msg, Map<String, String> data) {
        @Override
        public String toString() {
            return level + "('" + msg + "')" + (data.isEmpty() ? "" : " data=" + data);
        }
    }

    static List<RecCall> execProxy(ClassLoader cl, String scenario, String className, Driver.Run run, String loggerName) throws Exception {
        var cls = cl.loadClass("gen." + scenario + "." + className);
        var sink = new java.util.ArrayList<RecCall>();
        var factory = new org.slf4j.ILoggerFactory() {
            @Override
            public org.slf4j.Logger getLogger(String name) {
                return new check.RecLogger(name, new check.RecLogger.RecLogSink() {
                    @Override
                    public void record(check.RecLogger.Call call) {
                        Map<String, String> data = java.util.Collections.emptyMap();
                        if (call.marker() != null) {
                            var gen = new check.RecGen();
                            try {
                                ((ru.tinkoff.kora.logging.common.arg.StructuredArgumentWriter) call.marker()).writeTo(gen);
                            } catch (IOException e) {
                                throw new RuntimeException(e);
                            }
                            data = new java.util.LinkedHashMap<>(gen.data);
                        }
                        sink.add(new RecCall(call.level(), call.msg(), data));
                    }
                });
            }
        };

        var ctors = cls.getConstructors();
        Object[] ctorArgs;
        if (run.hasMapper()) {
            ctorArgs = new Object[]{factory, mapper()};
        } else {
            ctorArgs = new Object[]{factory};
        }
        Object instance = null;
        for (Constructor<?> c : ctors) {
            if (c.getParameterCount() == ctorArgs.length) {
                instance = c.newInstance(ctorArgs);
                break;
            }
        }
        if (instance == null) throw new IllegalStateException("no ctor for " + className);

        var scope = new java.util.ArrayList<RecCall>();
        var log = (check.RecLogger) factory.getLogger(loggerName);
        log.disableAll();
        for (String lvl : run.levels()) {
            log.enable(lvl);
        }

        var m = instance.getClass().getMethod("test", paramTypes(scenario));
        Object result = m.invoke(instance, run.args());
        if (result instanceof java.util.concurrent.CompletionStage<?> cs) {
            cs.toCompletableFuture().join();
        }
        return new java.util.ArrayList<>(sink);
    }

    static Object mapper() {
        if (MapperClassHolder.MAPPER != null) {
            return MapperClassHolder.MAPPER;
        }
        throw new IllegalStateException();
    }

    static class MapperClassHolder {
        static final Object MAPPER = new ru.tinkoff.kora.logging.common.arg.StructuredArgumentMapper<String>() {
            @Override
            public void write(com.fasterxml.jackson.core.JsonGenerator gen, String value) throws IOException {
                gen.writeString("mapped-" + value);
            }
        };
    }

    static Class<?>[] paramTypes(String scenario) {
        var s = byId(scenario);
        var types = new Class<?>[s.params().size()];
        for (int i = 0; i < s.params().size(); i++) {
            var t = s.params().get(i).typeText();
            if (t.equals("int")) types[i] = int.class;
            else if (t.equals("boolean")) types[i] = boolean.class;
            else if (t.equals("java.lang.String")) types[i] = String.class;
            else throw new IllegalStateException("unhandled param type " + t);
        }
        return types;
    }

    static Scenario byId(String id) {
        for (var s : SCENARIOS) {
            if (s.id().equals(id)) return s;
        }
        throw new IllegalArgumentException(id);
    }

    static String renderCalls(List<RecCall> calls) {
        return String.valueOf(calls);
    }
}

